//! Upstream's shared test vectors (generated by upstream from its Rust
//! binaries) must still match byte for byte after Akshara's patches.

use teltools::{hin2tel, iast2tel, tel2hin, tel2iast, trans, trans_with, TransOptions};

fn lines(name: &str) -> Vec<String> {
    let path = format!("{}/tests/data/{}", env!("CARGO_MANIFEST_DIR"), name);
    std::fs::read_to_string(path)
        .expect("vector file")
        .replace("\r\n", "\n")
        .trim_end_matches('\n')
        .split('\n')
        .map(str::to_owned)
        .collect()
}

fn check(f: &dyn Fn(&str) -> String, input: &str, expected: &str) {
    let (src, exp) = (lines(input), lines(expected));
    assert_eq!(src.len(), exp.len());
    for (i, (s, e)) in src.iter().zip(&exp).enumerate() {
        assert_eq!(&f(s), e, "{input} line {}", i + 1);
    }
}

#[test]
fn trans_matches_upstream_binaries() {
    check(&|s| trans(s), "corpus_trans.txt", "expected_trans.txt");
}

#[test]
fn script_converters_match_upstream_binaries() {
    check(&|s| s.chars().map(tel2hin).collect(), "vectors_tel.txt", "expected_tel2hin.txt");
    check(&|s| s.chars().map(hin2tel).collect(), "vectors_dev.txt", "expected_hin2tel.txt");
    check(&|s| tel2iast(s), "vectors_tel.txt", "expected_tel2iast.txt");
    check(&|s| iast2tel(s), "vectors_iast.txt", "expected_iast2tel.txt");
}

#[test]
fn live_mode_differs_only_where_upstream_keyboard_documents() {
    // Upstream keyman/README.md: om-family and <tag> lines are the only
    // divergences between the keyboard ("sensible mode") and trans().
    let (src, exp) = (lines("corpus_trans.txt"), lines("expected_trans.txt"));
    let mut divergent = 0;
    for (s, e) in src.iter().zip(&exp) {
        let live = trans_with(s, &TransOptions::LIVE);
        if &live != e {
            divergent += 1;
            let explained = s.contains("om") || s.contains("OM") || s.contains("AUM") || s.contains('<');
            assert!(explained, "unexpected divergence for {s:?}: {live:?} vs {e:?}");
        }
    }
    assert_eq!(divergent, 6, "upstream documents 6 divergences");
    assert_eq!(trans_with("komala", &TransOptions::LIVE), "కొమల");
    assert_eq!(trans("komala"), "కॐఅల", "upstream batch quirk preserved");
    assert_eq!(trans_with("\\om", &TransOptions::LIVE), "ॐ");
    assert_eq!(trans_with("a<b>ka", &TransOptions::LIVE), "అ<బ్>క");
    assert_eq!(trans("a<b>ka"), "అ<b>క", "batch mode copies tags through");
}

#[test]
fn non_ascii_input_no_longer_panics() {
    for s in ["నమస్తే", "ka😀ma", "é", "k\u{0301}", "a<😀>b", "日本語"] {
        let _ = trans(s);
        let _ = trans_with(s, &TransOptions::LIVE);
    }
    assert_eq!(trans_with("ka😀ma", &TransOptions::LIVE), "క😀మ");
    assert_eq!(trans("రామ rAma"), "రామ రామ");
}
